<?php
declare(strict_types=1);
use CoreCMS\Core\Csrf;
use CoreCMS\Core\Url;
use CoreCMS\Modules\HairSalon\HairSalonManager;
require_once dirname(__DIR__).'/Admin/HairSalonManager.php';
return static function(PDO $db,array $params,array $request,array $module):string{
 CoreCMS\Core\Auth::startSession();$m=new HairSalonManager($db);$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$base=Url::to('/salon');$message='';
 if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
  Csrf::requireValidPost();
  try{if(trim((string)($_POST['website']??''))==='')$m->createAppointment($_POST,(string)($_SERVER['REMOTE_ADDR']??''));$message='Randevu talebiniz alındı. Ekibimiz en kısa sürede sizinle iletişime geçecek.';}
  catch(Throwable $error){$message='Seçtiğiniz saat artık uygun olmayabilir. Lütfen başka bir saat seçerek tekrar deneyin.';}
  return '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="'.Url::to('/modules/hair-salon/assets/css/hair-salon.css').'"><title>Randevu talebi</title></head><body class="hs-site"><main class="hs-container"><section class="hs-result"><h1>'.$e($message).'</h1><a class="hs-button" href="'.$base.'">Hizmetlere dön</a></section></main></body></html>';
 }
 $services=$m->services(true);$selectedService=(int)($_GET['service_id']??0);$selectedStaff=(int)($_GET['staff_id']??0);$date=(string)($_GET['date']??(new DateTimeImmutable('tomorrow'))->format('Y-m-d'));
 $staff=$m->staff(true,$selectedService);$slots=$selectedService&&$selectedStaff&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)?$m->availableSlots($selectedService,$selectedStaff,$date):[];
 $html='<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online Randevu</title><link rel="stylesheet" href="'.Url::to('/modules/hair-salon/assets/css/hair-salon.css').'"></head><body class="hs-site"><header class="hs-header"><a class="hs-brand" href="'.$base.'">ATELIER<span>.</span></a><a href="'.$base.'">← Hizmetler</a></header><main class="hs-container"><section class="hs-booking-page"><span>ONLINE RANDEVU</span><h1>Kendinize zaman ayırın.</h1><p>Hizmetinizi, uzmanınızı ve size uygun saati seçin.</p><form method="get" class="hs-picker"><label>Hizmet<select name="service_id" required><option value="">Hizmet seçin</option>';foreach($services as $s)$html.='<option value="'.(int)$s['id'].'"'.($selectedService===(int)$s['id']?' selected':'').'>'.$e($s['name']).' · '.(int)$s['duration_minutes'].' dk · '.number_format((float)$s['price'],0,',','.').' '.$e($s['currency']).'</option>';$html.='</select></label><label>Uzman<select name="staff_id" required><option value="">Uzman seçin</option>';foreach($staff as $p)$html.='<option value="'.(int)$p['id'].'"'.($selectedStaff===(int)$p['id']?' selected':'').'>'.$e($p['name']).' · '.$e($p['title']).'</option>';$html.='</select></label><label>Tarih<input type="date" name="date" min="'.date('Y-m-d').'" value="'.$e($date).'" required></label><button class="hs-button">Uygun saatleri göster</button></form>';
 if($selectedService&&$selectedStaff){$html.='<section class="hs-slots"><h2>Uygun saatler</h2>';if($slots){$html.='<form method="post" class="hs-appointment-form"><input type="hidden" name="service_id" value="'.$selectedService.'"><input type="hidden" name="staff_id" value="'.$selectedStaff.'"><input type="hidden" name="date" value="'.$e($date).'"><div class="hs-time-grid">';foreach($slots as $i=>$slot)$html.='<label><input type="radio" name="time" value="'.$e($slot).'" '.($i===0?'checked':'').'><span>'.$e($slot).'</span></label>';$html.='</div><div class="hs-customer-grid"><label>Ad soyad<input name="customer_name" maxlength="160" required></label><label>E-posta<input type="email" name="email" maxlength="190" required></label><label>Telefon<input name="phone" maxlength="60"></label><label class="hs-full">Notunuz<textarea name="message" rows="3" maxlength="3000"></textarea></label><label class="hs-honey">Web sitesi<input name="website" tabindex="-1" autocomplete="off"></label></div>'.Csrf::field().'<button class="hs-button">Randevu talebi gönder</button></form>';}else $html.='<div class="hs-empty">Bu gün için uygun saat bulunamadı. Başka bir tarih veya uzman seçin.</div>';$html.='</section>';}
 return $html.'</section></main><footer class="hs-footer">ATELIER. · '.date('Y').'</footer></body></html>';
};
